// 优化后的代码
function calculateTotal(items: Array<{ price: number; quantity: number }> = []): number {
  return items.reduce((sum, { price = 0, quantity = 0 }) => sum + price * quantity, 0);
}

// 优化点：
// 1. 使用 Array.reduce 替代 for 循环，更简洁
// 2. 添加参数默认值，处理空值情况
// 3. 使用解构赋值简化代码
// 4. 添加类型定义，提升代码健壮性
// 5. 函数式编程风格，易于维护

